import type { FilterDataStructure, FilterForm } from 'models/Filters';

import { getInnovationHubGeoLabel } from './getInnovationHubGeoLabel';

type FormatMessageFn = (
  descriptor: { id: string },
  values?: Record<string, string>,
) => string;

export function formatScopedGeoTitle(
  formatMessage: FormatMessageFn,
  params: {
    applied: FilterForm | null | undefined;
    dataFilters: FilterDataStructure;
    globalTitleId: string;
    scopedTitleId: string;
    resolveScope?: (
      dataFilters: FilterDataStructure,
      applied: FilterForm,
    ) => string;
  },
): string {
  const { applied, dataFilters, globalTitleId, scopedTitleId, resolveScope } =
    params;

  let scope = '';
  if (applied) {
    scope = resolveScope
      ? resolveScope(dataFilters, applied)
      : getInnovationHubGeoLabel(dataFilters, applied);
  }
  scope = scope.trim();
  if (!scope) {
    return formatMessage({ id: globalTitleId });
  }
  return formatMessage({ id: scopedTitleId }, { scope });
}
